import cv2from ultralytics import YOLOfrom src.tracking import trackingfrom src.tracking import counter_carmodel = YOLO("model/yolo26s.pt")cap  = cv2.VideoCapture('data/ScreenRecorderProject49.mp4')DEFAULT_WIDTH = 1280DEFAULT_HEIGHT = 720cap.set(cv2.CAP_PROP_FRAME_WIDTH, DEFAULT_WIDTH)cap.set(cv2.CAP_PROP_FRAME_HEIGHT, DEFAULT_HEIGHT)fps = cap.get(cv2.CAP_PROP_FPS)frame_count = cap.get(cv2.CAP_PROP_FRAME_COUNT)width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))writer = cv2.VideoWriter("final/output.mp4",                          cv2.VideoWriter_fourcc(*'mp4v'),                          fps, (DEFAULT_WIDTH, DEFAULT_HEIGHT))start_line = (1000,720)end_line = (1000,360)a_start_line = (400,720)a_end_line = (400,360)while True:    ret, frame = cap.read()    frame = cv2.resize(frame, (DEFAULT_WIDTH, DEFAULT_HEIGHT))    frame = tracking(frame, model, start_line, a_start_line)    #Линия подсчёта    overlay = frame.copy()    cv2.line(overlay,start_line,end_line,(0,255,0),12)    cv2.line(overlay,a_start_line,a_end_line,(0,0,255),12)    frame = cv2.addWeighted(overlay,0.5,frame,0.5,0)    cv2.putText(frame, str(len(counter_car)), end_line, cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 0, 255), 2)    #Растояние 2,7 метра, но на видео постоянно скачет горизонт, да и детектит плохо машины    cv2.imshow("Output", frame)    writer.write(frame)    if cv2.waitKey(1) & 0xFF == ord('q'):        breakcap.release()writer.release()cv2.destroyAllWindows()